Q: Javascript multiple inheritance A: <p>In the book Beginning Node.js by Basarat Syed, he shows an inheritance pattern.   This code demonstrates his way of setting up the prototype chain. It uses the util module to as a helper to link the prototype chains. </p>

<p>From page 91, "Javascript supports prototypical inheritance. Chapter 2 of his book explains how a prototype works. In JavaScript, a member is looked up on the current item (such as item.foo), which is followed by its prototype (item.<strong>proto</strong>.foo), which is followed by it prototype's prototype (item.<strong>proto</strong>.<strong>proto</strong>.foo), an so on until the prototype itself (for example, item.<strong>proto</strong>.<strong>proto</strong>.<strong>proto</strong>) is null." - Basarat Syed</p>

<p>Note: The stack overflow editor stripped of the "__" prefix and suffix from proto.</p>

<p>Sample code.  Base class is Animal, Bird class is derived from Animal, and Superman class is derived from Bird.</p>

<pre><code>var inherits = require('util').inherits;

// Animal class, the parent
function Animal(name){
    this.name = name;

    // Additional initialization code
}

Animal.prototype.walk = function(destination){
    console.log(this.name,'is walking to',destination);
}

Animal.prototype.eat = function(food){
    console.log(this.name,'is eating',food);
}

// Bird class, child of Animal
function Bird(name){
    // call the Animal constructor
    Animal.call(this,name);

    // Additional initialization code
}

Bird.prototype.fly = function(destination){
    console.log(this.name,'is flying to',destination);
}

// Setup the prototype chain from child Bird to parent Animal
inherits(Bird,Animal);

// Superman class, child of Bird
function Superman(name){
    // Call the Bird constructor
    Bird.call(this,name);

    // Additional initialization code
}

Superman.prototype.jump = function(destination){
    console.log(this.name,'jumped over a',destination);
}

// Setup the prototype chain from child Superman to parent Bird
inherits(Superman,Bird);

// Create the parent instance
var animal = new Animal('elephant');
animal.walk('melbourne');
animal.eat('grass');

// Create the child of animal instance
var bird = new Bird('sparrow');
bird.walk('sydney');
bird.fly('melbourne');
bird.eat('seeds');

// Create the child of bird instance
var superman = new Superman('Clark Kent');
superman.fly('Gotham');
superman.walk('Daily planet');
superman.jump('Building');
superman.eat('Hot dogs');
</code></pre>

